css:
* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: transparent !important;
}

.alarm-widget {
  position: relative;

  width: 100%;
  height: 100%;
  padding: 100px 60px 30px;

  container-type: size;
  background: transparent;
  color: #223441;

  font-family:
    Bahnschrift,
    "Segoe UI",
    Arial,
    sans-serif;

  user-select: none;
  pointer-events: none;
  opacity: var(--w-opacity, 1);
}

.alarm-board {
  --slot-width:
    clamp(116px, calc(9.6cqw + 30px), 200px);

  --column-gap:
    clamp(36px, calc(1.45cqw + 20px), 44px);

  display: grid;
  grid-template-columns: repeat(2, max-content);
  grid-template-rows: minmax(0, 1fr);

  column-gap: var(--column-gap);
  row-gap: 0;
  align-content: space-between;

  width: max-content;
  max-width: 100%;
  height: 100%;
  margin: 0 auto;
}

/* Ambas columnas utilizan el alto disponible hasta el margen inferior.
 * Se conservan los anchos, separaciones horizontales y cuadros de 38 px.
 */
.alarm-column {
  display: grid;
  grid-template-columns: max-content var(--slot-width);
  grid-template-rows: repeat(var(--alarm-rows), 38px);
  column-gap: var(--column-gap);
  align-content: space-between;
  height: 100%;
  min-height: 0;
}

.alarm-row {
  display: contents;
}

.alarm-label {
  display: flex;
  align-items: center;
  align-self: stretch;

  height: 100%;

  color: #223441;
  font-size: clamp(15px, 1.35cqw, 20px);
  font-weight: 700;
  line-height: 1.12;
  white-space: nowrap;
}

.alarm-label--pink {
  color: #ff00ff;
}

.alarm-cell {
  display: flex;
  align-items: center;
  justify-content: center;

  width: 100%;
  height: 38px;
}

.alarm-slot {
  width: 100%;
  height: 38px;

  border: 1px solid #687984;
  border-radius: 2px;
  background: linear-gradient(180deg, #e3e5e7, #d7d8db);

  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.8),
    inset 0 -1px 2px rgba(47, 60, 69, 0.09),
    0 1px 2px rgba(32, 48, 61, 0.12);
}


/* Solo texto: encabezado transparente con la tipografía del ejemplo de recetas. */
.alarm-header {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 70px;
  min-width: 0;
  padding: 14px 30px 0;
  overflow: hidden;
  background: transparent;
  font-family: Arial, Helvetica, sans-serif;
  user-select: none;
}

.alarm-title {
  margin: 0;
  padding: 0;
  color: #0E5B67;
  font-size: 28px;
  font-weight: 700;
  line-height: 1.05;
  white-space: nowrap;
}

.alarm-subtitle {
  margin: 5px 0 0;
  padding: 0;
  color: #728DA5;
  font-size: 14px;
  font-weight: 400;
  line-height: 1.3;
  white-space: nowrap;
}

