"use strict";

(function () {
  const DEFAULT_TITLE = "LÍNEA 3 / HABILITACIÓN DE ALARMAS";
  const DEFAULT_SUBTITLE = "Habilitación de alarmas de las variables del proceso";

  let headerTitle = null;
  let headerSubtitle = null;

  /* NOMBRE: Título//Subtítulo. Con Título// se oculta el subtítulo.
   * Sin NOMBRE se muestran ambos textos predeterminados.
   * Sin separador se personaliza solo el título.
   */
  function updateHeader(widget) {
    if (!headerTitle || !headerSubtitle) return;
    const name = widget && typeof widget.name === "string"
      ? widget.name.trim() : "";
    const separator = name.indexOf("//");
    const titleText = separator >= 0 ? name.slice(0, separator).trim() : name;
    const subtitleText = separator >= 0
      ? name.slice(separator + 2).trim() : DEFAULT_SUBTITLE;

    headerTitle.textContent = titleText || DEFAULT_TITLE;
    headerSubtitle.textContent = subtitleText;
    headerSubtitle.hidden = subtitleText === "";
    fitHeader();
  }

  function fitHeader() {
    [[headerTitle, 28], [headerSubtitle, 14]].forEach(function (entry) {
      const element = entry[0];
      if (!element || element.hidden) return;
      const size = entry[1];
      element.style.fontSize = size + "px";
      const available = element.clientWidth;
      if (available > 0 && element.scrollWidth > available) {
        element.style.fontSize = (size * available / element.scrollWidth) + "px";
      }
    });
  }

  let latestWidget = null;
  let headerObserver = null;

  const LEFT_LABELS = Array.from(
    { length: 14 },
    function (_, index) {
      return "Cuba de Lavado " + (index + 1);
    }
  );

  const RIGHT_LABELS = [
    "Flujo Preparación",
    "Flujo de Agua",
    "T. Vapor Secador",
    "F. Vapor Secador",
    "P. Rodillos Rizadora",
    "Calef. Rizadoras 1-8",
    "P. Cajas Rizadoras",
    "Conductividad",
    "Tanque Dosificador",
    "Tanque de Mezcla",
    "Corriente MP"
  ];

  const PINK_ROWS = new Set([2, 3, 4]);

  function make(tag, className, parent, text) {
    const element = document.createElement(tag);
    element.className = className;

    if (text !== undefined) {
      element.textContent = text;
    }

    parent.appendChild(element);
    return element;
  }

  function makeEmptyCell(parent) {
    const cell = make("div", "alarm-cell", parent);
    const slot = make("div", "alarm-slot", cell);
    slot.setAttribute("aria-hidden", "true");
  }

  function makeColumn(labels, isRight, parent) {
    const column = make("div", "alarm-column", parent);
    column.style.setProperty("--alarm-rows", String(labels.length));
    labels.forEach(function (text, index) {
      const row = make("div", "alarm-row", column);
      make(
        "div",
        isRight && PINK_ROWS.has(index)
          ? "alarm-label alarm-label--pink"
          : "alarm-label",
        row,
        text
      );
      makeEmptyCell(row);
    });
  }

  function buildWidget() {
    const board = document.getElementById("alarm-board");
    if (!board) return;

    board.replaceChildren();

    makeColumn(LEFT_LABELS, false, board);
    makeColumn(RIGHT_LABELS, true, board);

    headerTitle = document.querySelector(".alarm-title");
    headerSubtitle = document.querySelector(".alarm-subtitle");
    updateHeader(latestWidget || window.WIDGET || null);

    if (typeof ResizeObserver !== "undefined") {
      headerObserver = new ResizeObserver(fitHeader);
      headerObserver.observe(document.querySelector(".alarm-header"));
    } else {
      window.addEventListener("resize", fitHeader);
    }
  }

  /* Widget visual: no recibe variables del PLC. */
  window.onWidgetUpdate = function (widget) {
    latestWidget = widget;
    updateHeader(widget);
  };

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      buildWidget,
      { once: true }
    );
  } else {
    buildWidget();
  }
})();
